-- Keep fiscal configuration SELECT separate from privileged writes.
drop policy if exists erp_config_fiscal_write_tenant on public.erp_config_fiscal;
create policy erp_config_fiscal_insert_tenant on public.erp_config_fiscal for insert to authenticated with check ((exists (select 1 from public.erp_usuarios u where u.auth_user_id=(select auth.uid()) and u.ativo=true and u.deleted_at is null and ((u.empresa_id=erp_config_fiscal.empresa_id) or u.is_master=true) and upper(coalesce(u.perfil,''))=any(array['MASTER','ADMIN','ADMINISTRADOR']))));
create policy erp_config_fiscal_update_tenant on public.erp_config_fiscal for update to authenticated using ((exists (select 1 from public.erp_usuarios u where u.auth_user_id=(select auth.uid()) and u.ativo=true and u.deleted_at is null and ((u.empresa_id=erp_config_fiscal.empresa_id) or u.is_master=true) and upper(coalesce(u.perfil,''))=any(array['MASTER','ADMIN','ADMINISTRADOR'])))) with check ((exists (select 1 from public.erp_usuarios u where u.auth_user_id=(select auth.uid()) and u.ativo=true and u.deleted_at is null and ((u.empresa_id=erp_config_fiscal.empresa_id) or u.is_master=true) and upper(coalesce(u.perfil,''))=any(array['MASTER','ADMIN','ADMINISTRADOR']))));
create policy erp_config_fiscal_delete_tenant on public.erp_config_fiscal for delete to authenticated using ((exists (select 1 from public.erp_usuarios u where u.auth_user_id=(select auth.uid()) and u.ativo=true and u.deleted_at is null and ((u.empresa_id=erp_config_fiscal.empresa_id) or u.is_master=true) and upper(coalesce(u.perfil,''))=any(array['MASTER','ADMIN','ADMINISTRADOR']))));